/*! xhtml v1.0.0 - Unlicensed - inspired by htmx */

function hydrate(parent) {
  for(const method of ["get", "delete", "post", "put", "patch"]) {
    const nodes = [...parent.querySelectorAll(`[x-${method}]`)];
    if(parent.hasAttribute(`x-${method}`)) nodes.push(parent);

    nodes.forEach((node) => {
      let url = node.getAttribute(`x-${method}`);
      let event = node.getAttribute("x-on");

      const target = node.getAttribute("x-target") || "@self";
      const replace = node.getAttribute("x-replace") || "innerHTML";
      const params = node.getAttribute("x-params") || "@self";

      if(!event) {
        switch(true) {
          case node instanceof HTMLFormElement: event = "submit"; break;
          case node instanceof HTMLButtonElement: event = "click"; break;
          case node instanceof HTMLAnchorElement: event = "click"; break;
          case node instanceof HTMLInputElement && node.type == "button": event = "click"; break;
          case node instanceof HTMLInputElement && node.type == "submit": event = "click"; break;
          case node instanceof HTMLInputElement: event = "input"; break;
          case node instanceof HTMLSelectElement: event = "input"; break;
          case node instanceof HTMLTextAreaElement: event = "input"; break;
          default: event = "load"; break;
        }
      }

      const confirmMessage = node.getAttribute("x-confirm");
      const promptMessage = node.getAttribute("x-prompt");
      const promptAs = node.getAttribute("x-prompt-as") || "value";

      if(!["load", "click", "mouseover", "input", "submit"].includes(event)) {
        throw new Error(`Malformed x-on: '${event}'.`);
      }

      if(replace != "innerHTML" && replace != "outerHTML") {
        throw new Error(`Malformed x-replace: '${replace}'.`);
      }

      const handler = async () => {
        // Exit early if confirm was denied.
        if(confirmMessage && !confirm(confirmMessage)) return; 

        const element = target == "@self" ? node : document.querySelector(target);
        if(!element) throw new Error(`No element found for selector '${target}'.`);

        const isJSON = (str) => {
          try {
            JSON.stringify(JSON.parse(str));
            return true;
          } catch (e) {
            return false;
          }
        };

        let body = {};

        if(isJSON(params)) {
          body = JSON.parse(params);
        }
        else {
          const element = params == "@self" ? node : document.querySelector(params);
          if(!element) throw new Error(`No element found for selector '${params}'.`);

          const extractData = (form) => {
            const object = {};
            (new FormData(form)).forEach((value, key) => object[key] = value);
            return object;
          }

          // For <form> elements, get the FormDatam, for other elements, get the dataset.
          body = element instanceof HTMLFormElement ? extractData(element) : element.dataset;
        }

        if(promptMessage) body[promptAs] = prompt(promptMessage);

        element.setAttribute("x-loading", "");

        const request = { method, headers: { "Accept": "text/html" } };

        if(["post", "put", "patch"].includes(method)) {
          // Sidenote: this corrupts nested JSON structures like
          // `{"nested":{"foo":"bar"}}`, if passed via x-params.
          request.body = new URLSearchParams(body);
        } else {
          url += `?${new URLSearchParams(body)}`;
        }

        const response = await fetch(url, request);

        // On 'No Content' or 'Not Modified' responses, do nothing, as
        // prescribed by the HTTP specification.
        if(response.status == 204 || response.status == 304) return;

        element.removeAttribute("x-loading");

        let nodes = [];

        if(replace == "innerHTML") {
          element.innerHTML = await response.text();
          nodes = Array.from(element.children);
        }
        else  {
          const template = document.createElement("template");
          template.innerHTML = await response.text();
          nodes = Array.from(template.content.children);
          element.replaceWith(template.content);
        }

        for (const element of nodes) {
          hydrate(element);

          // When inserting scripts via innerHTML or outerHTML, the scripts do
          // not automatically get executed. The following loop recreates the
          // current script element or any child script elements. By reinserting
          // them in the DOM via appendChild, the JavaScript *does* get executed.
          
          // Please note that this can lead to 'redeclaration' errors if global
          // variables are created. This can be circumvented by using an IIFE or
          // by setting type="module" on the script element.

          const scripts = element instanceof HTMLScriptElement ?
            [element] : element.querySelectorAll("script");

          for (const deadScript of scripts) {
            const hydratedScript = document.createElement("script");

            Array.from(deadScript.attributes).forEach(attr => {
              hydratedScript.setAttribute(attr.name, attr.value) 
            });

            const scriptText = document.createTextNode(deadScript.innerHTML);
            hydratedScript.appendChild(scriptText);

            deadScript.parentNode.replaceChild(hydratedScript, deadScript);
          }
        }
      };

      if(event == "load") handler();
      else node.addEventListener(event, (e) => {
        e.preventDefault();
        handler();
        if(e.target instanceof HTMLFormElement) e.target.reset();
      });
    });
  }
}

// When the DOM finishes loading, hydrate all x-* tags.
document.addEventListener("DOMContentLoaded", () => hydrate(document.body));
